#-----------------------------------------------------------------------------
$ErrorActionPreference = 'Stop'
# The app reads this output through a pipe as UTF-8; without this, monitor labels with
# a middle dot come through in the OEM code page and print as replacement characters.
try { [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding $false } catch { }
$ScriptDir     = Split-Path -Parent $MyInvocation.MyCommand.Path
$LogPath       = Join-Path $ScriptDir 'switch.log'
$LockPath      = Join-Path $AppRoot 'switch.lock'
$SettleSeconds = 2   # Windows finishes an apply asynchronously; verify waits this long first
$StepCount     = 3
$script:CurrentStep = 0
$script:CurrentStepName = ''

# Every line printed also lands in switch.log with a timestamp, so a run started
# from a shortcut can be checked afterwards.
function Write-Host {
    param([Parameter(Position = 0, ValueFromRemainingArguments = $true)]$Object, [ConsoleColor]$ForegroundColor, [switch]$NoNewline)
    $text = "$Object"
    try { Add-Content -Path $LogPath -Value ("{0:yyyy-MM-dd HH:mm:ss}  {1}" -f (Get-Date), $text) -Encoding UTF8 } catch { }
    if ($PSBoundParameters.ContainsKey('ForegroundColor')) { Microsoft.PowerShell.Utility\Write-Host $text -ForegroundColor $ForegroundColor -NoNewline:$NoNewline }
    else { Microsoft.PowerShell.Utility\Write-Host $text -NoNewline:$NoNewline }
}

# One stable line per status change; the app parses these and a person can read them.
function Write-Step([int]$step, [string]$status, [string]$text) {
    $script:CurrentStep = $step
    $script:CurrentStepName = $text
    $color = switch ($status) { 'done' { 'Green' } 'failed' { 'Red' } 'skipped' { 'DarkGray' } default { 'Cyan' } }
    Write-Host ("[{0}/{1}] {2} {3}" -f $step, $StepCount, $status, $text) -ForegroundColor $color
}

# A failure line says what to do next, then what went wrong, then the Windows error code.
function Write-Failure([string]$action, [string]$reason, [int]$code) {
    $text = '{0}: {1}; {2}' -f $script:CurrentStepName, $action, $reason
    if ($code -ne 0) { $text += (' (Windows error {0})' -f $code) }
    Write-Step $script:CurrentStep 'failed' $text
}

function Finish([int]$code) {
    if (Test-Path $LockPath) {
        try { $owner = Get-Content $LockPath -First 1 } catch { $owner = '' }
        if ($owner -eq "pid=$PID") { try { Remove-Item $LockPath -Force } catch { } }
    }
    Write-Host ("Exit code {0}" -f $code)
    if ($Pause) {
        Microsoft.PowerShell.Utility\Write-Host ""
        Microsoft.PowerShell.Utility\Write-Host "Press any key to close..." -ForegroundColor DarkGray
        try { [void][Console]::ReadKey($true) } catch { Start-Sleep -Seconds 15 }
    }
    exit $code
}

$csharp = @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;

namespace LayoutswapSwitch {
    [StructLayout(LayoutKind.Sequential)] public struct LUID { public uint Low; public int High; }
    [StructLayout(LayoutKind.Sequential)] public struct RATIONAL { public uint Num; public uint Den; }
    [StructLayout(LayoutKind.Sequential)] public struct PATH_SOURCE { public LUID adapterId; public uint id; public uint modeInfoIdx; public uint statusFlags; }
    [StructLayout(LayoutKind.Sequential)] public struct PATH_TARGET {
        public LUID adapterId; public uint id; public uint modeInfoIdx; public uint outputTechnology; public uint rotation;
        public uint scaling; public RATIONAL refreshRate; public uint scanLineOrdering; public int targetAvailable; public uint statusFlags; }
    [StructLayout(LayoutKind.Sequential)] public struct PATH_INFO { public PATH_SOURCE source; public PATH_TARGET target; public uint flags; }

    // 64-byte DISPLAYCONFIG_MODE_INFO; the union is kept as raw 8-byte words and
    // overlaid with the source-mode fields we want to read (width/height/position).
    [StructLayout(LayoutKind.Explicit, Size = 64)] public struct MODE_INFO {
        [FieldOffset(0)]  public uint infoType;
        [FieldOffset(4)]  public uint id;
        [FieldOffset(8)]  public LUID adapterId;
        [FieldOffset(16)] public ulong u0; [FieldOffset(24)] public ulong u1; [FieldOffset(32)] public ulong u2;
        [FieldOffset(40)] public ulong u3; [FieldOffset(48)] public ulong u4; [FieldOffset(56)] public ulong u5;
        [FieldOffset(16)] public uint srcWidth; [FieldOffset(20)] public uint srcHeight;
        [FieldOffset(24)] public uint srcPixelFormat; [FieldOffset(28)] public int srcX; [FieldOffset(32)] public int srcY;
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] public struct TARGET_NAME {
        public uint type; public uint size; public LUID adapterId; public uint id;
        public uint flags; public uint outputTechnology; public ushort edidMfg; public ushort edidProd; public uint connectorInstance;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 64)]  public string friendlyName;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string devicePath; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] public struct ADAPTER_NAME {
        public uint type; public uint size; public LUID adapterId; public uint id;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string devicePath; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] public struct SOURCE_NAME {
        public uint type; public uint size; public LUID adapterId; public uint id;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string gdiName; }

    // One row per path with every field flattened, so the PowerShell side never
    // edits a nested struct (see docs/windows-behaviour.md).
    public class PathRow {
        public bool Active; public bool Available; public bool HasMode;
        public string SourceAdapter; public string TargetAdapter; public string Monitor; public string Friendly; public string Gdi;
        public uint Rotation; public uint RefreshNum; public uint RefreshDen; public int X, Y, W, H;
    }

    public static class Api {
        const uint QDC_ALL_PATHS = 1, QDC_ONLY_ACTIVE_PATHS = 2, PATH_ACTIVE = 1, IDX_INVALID = 0xFFFFFFFF;
        const uint SDC_USE_SUPPLIED_DISPLAY_CONFIG = 0x20, SDC_VALIDATE = 0x40, SDC_APPLY = 0x80, SDC_SAVE_TO_DATABASE = 0x200, SDC_ALLOW_CHANGES = 0x400;

        [DllImport("user32.dll")] static extern int GetDisplayConfigBufferSizes(uint flags, out uint nPaths, out uint nModes);
        [DllImport("user32.dll")] static extern int QueryDisplayConfig(uint flags, ref uint nPaths, [Out] PATH_INFO[] paths, ref uint nModes, [Out] MODE_INFO[] modes, IntPtr topo);
        [DllImport("user32.dll")] static extern int SetDisplayConfig(uint nPaths, PATH_INFO[] paths, uint nModes, MODE_INFO[] modes, uint flags);
        [DllImport("user32.dll")] static extern int DisplayConfigGetDeviceInfo(ref TARGET_NAME p);
        [DllImport("user32.dll")] static extern int DisplayConfigGetDeviceInfo(ref ADAPTER_NAME p);
        [DllImport("user32.dll")] static extern int DisplayConfigGetDeviceInfo(ref SOURCE_NAME p);

        static string AdapterName(LUID id) {
            var a = new ADAPTER_NAME { type = 4, size = (uint)Marshal.SizeOf(typeof(ADAPTER_NAME)), adapterId = id };
            return DisplayConfigGetDeviceInfo(ref a) == 0 ? a.devicePath : "";
        }

        public static PathRow[] Query(bool activeOnly) {
            uint flags = activeOnly ? QDC_ONLY_ACTIVE_PATHS : QDC_ALL_PATHS;
            uint np, nm;
            int rc = GetDisplayConfigBufferSizes(flags, out np, out nm);
            if (rc != 0) throw new Exception("GetDisplayConfigBufferSizes failed with error " + rc);
            var paths = new PATH_INFO[np]; var modes = new MODE_INFO[nm];
            rc = QueryDisplayConfig(flags, ref np, paths, ref nm, modes, IntPtr.Zero);
            if (rc != 0) throw new Exception("QueryDisplayConfig failed with error " + rc);
            var rows = new PathRow[np];
            for (int i = 0; i < np; i++) {
                var p = paths[i];
                var r = new PathRow();
                r.Active = (p.flags & PATH_ACTIVE) != 0;
                r.Available = p.target.targetAvailable != 0;
                r.SourceAdapter = AdapterName(p.source.adapterId);
                r.TargetAdapter = AdapterName(p.target.adapterId);
                var t = new TARGET_NAME { type = 2, size = (uint)Marshal.SizeOf(typeof(TARGET_NAME)), adapterId = p.target.adapterId, id = p.target.id };
                if (DisplayConfigGetDeviceInfo(ref t) == 0) { r.Monitor = t.devicePath; r.Friendly = t.friendlyName; } else { r.Monitor = ""; r.Friendly = ""; }
                var s = new SOURCE_NAME { type = 1, size = (uint)Marshal.SizeOf(typeof(SOURCE_NAME)), adapterId = p.source.adapterId, id = p.source.id };
                r.Gdi = (r.Active && DisplayConfigGetDeviceInfo(ref s) == 0) ? s.gdiName : "";
                r.Rotation = p.target.rotation; r.RefreshNum = p.target.refreshRate.Num; r.RefreshDen = p.target.refreshRate.Den;
                uint mi = p.source.modeInfoIdx;
                if (r.Active && mi != IDX_INVALID && mi < nm && modes[mi].infoType == 1) {
                    r.HasMode = true; r.W = (int)modes[mi].srcWidth; r.H = (int)modes[mi].srcHeight; r.X = modes[mi].srcX; r.Y = modes[mi].srcY;
                }
                rows[i] = r;
            }
            return rows;
        }

        // Adapter LUIDs change on every boot; rewrite them from the saved adapter
        // device paths to whatever they are right now, then validate or apply.
        // Returns 0 on success, -1 when an adapter is missing (named in `missing`),
        // otherwise the SetDisplayConfig error code.
        public static int Apply(PATH_INFO[] paths, MODE_INFO[] modes, string[] srcAdapter, string[] tgtAdapter, string[] modeAdapter, out string missing, bool validateOnly) {
            var cur = Query(false);
            var map = new Dictionary<string, LUID>(StringComparer.OrdinalIgnoreCase);
            uint np, nm;
            GetDisplayConfigBufferSizes(QDC_ALL_PATHS, out np, out nm);
            var curPaths = new PATH_INFO[np]; var curModes = new MODE_INFO[nm];
            QueryDisplayConfig(QDC_ALL_PATHS, ref np, curPaths, ref nm, curModes, IntPtr.Zero);
            for (int i = 0; i < np && i < cur.Length; i++) {
                if (cur[i].SourceAdapter != "") map[cur[i].SourceAdapter] = curPaths[i].source.adapterId;
                if (cur[i].TargetAdapter != "") map[cur[i].TargetAdapter] = curPaths[i].target.adapterId;
            }
            var miss = new List<string>();
            for (int i = 0; i < paths.Length; i++) {
                LUID l;
                if (map.TryGetValue(srcAdapter[i], out l)) paths[i].source.adapterId = l; else if (!miss.Contains(srcAdapter[i])) miss.Add(srcAdapter[i]);
                if (map.TryGetValue(tgtAdapter[i], out l)) paths[i].target.adapterId = l; else if (!miss.Contains(tgtAdapter[i])) miss.Add(tgtAdapter[i]);
            }
            for (int j = 0; j < modes.Length; j++) { LUID l; if (map.TryGetValue(modeAdapter[j], out l)) modes[j].adapterId = l; }
            missing = string.Join(" ; ", miss.ToArray());
            if (miss.Count > 0) return -1;
            uint flags = SDC_USE_SUPPLIED_DISPLAY_CONFIG | SDC_ALLOW_CHANGES | (validateOnly ? SDC_VALIDATE : (SDC_APPLY | SDC_SAVE_TO_DATABASE));
            return SetDisplayConfig((uint)paths.Length, paths, (uint)modes.Length, modes, flags);
        }

        static T[] FromBytes<T>(byte[] buf) {
            int sz = Marshal.SizeOf(typeof(T)); var arr = new T[buf.Length / sz];
            var h = GCHandle.Alloc(buf, GCHandleType.Pinned);
            try { IntPtr p = h.AddrOfPinnedObject(); for (int i = 0; i < arr.Length; i++) arr[i] = (T)Marshal.PtrToStructure(new IntPtr(p.ToInt64() + i * sz), typeof(T)); }
            finally { h.Free(); }
            return arr;
        }
        // Non-generic wrappers: Windows PowerShell 5.1 cannot call generic methods directly.
        public static PATH_INFO[] BytesToPaths(byte[] b) { return FromBytes<PATH_INFO>(b); }
        public static MODE_INFO[] BytesToModes(byte[] b) { return FromBytes<MODE_INFO>(b); }
    }

    // The effective DPI of the monitor Windows shows under a GDI name, 0 when not found.
    public static class Dpi {
        [DllImport("user32.dll")] static extern bool SetProcessDpiAwarenessContext(IntPtr context);
        [DllImport("user32.dll")] static extern bool EnumDisplayMonitors(IntPtr hdc, IntPtr clip, MonitorEnumProc proc, IntPtr data);
        [DllImport("user32.dll", CharSet = CharSet.Auto)] static extern bool GetMonitorInfo(IntPtr hMon, ref MONITORINFOEX mi);
        [DllImport("shcore.dll")] static extern int GetDpiForMonitor(IntPtr hMon, int type, out uint dpiX, out uint dpiY);

        [StructLayout(LayoutKind.Sequential)] struct RECT { public int Left, Top, Right, Bottom; }
        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Auto)]
        struct MONITORINFOEX { public int cbSize; public RECT rcMonitor, rcWork; public uint dwFlags; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string szDevice; }
        delegate bool MonitorEnumProc(IntPtr hMon, IntPtr hdc, ref RECT r, IntPtr d);

        public static void MakeAware() { try { SetProcessDpiAwarenessContext(new IntPtr(-4)); } catch { } }

        public static uint ForGdi(string gdi) {
            IntPtr found = IntPtr.Zero;
            MonitorEnumProc cb = (IntPtr hMon, IntPtr hdc, ref RECT r, IntPtr d) => {
                var mi = new MONITORINFOEX { cbSize = Marshal.SizeOf(typeof(MONITORINFOEX)) };
                if (GetMonitorInfo(hMon, ref mi) && string.Equals(mi.szDevice.TrimEnd('\0'), gdi, StringComparison.OrdinalIgnoreCase)) found = hMon;
                return true; };
            EnumDisplayMonitors(IntPtr.Zero, IntPtr.Zero, cb, IntPtr.Zero);
            if (found == IntPtr.Zero) return 0;
            uint x, y;
            try { return GetDpiForMonitor(found, 0, out x, out y) == 0 ? x : 0; } catch { return 0; }
        }
    }
}
'@
if (-not ([System.Management.Automation.PSTypeName]'LayoutswapSwitch.Api').Type) {
    Add-Type -TypeDefinition $csharp -Language CSharp
}

#-----------------------------------------------------------------------------
# Helpers
#-----------------------------------------------------------------------------
function Get-Rows([bool]$activeOnly) { @([LayoutswapSwitch.Api]::Query($activeOnly)) }

# The live picture keyed by device path: one entry per monitor, the active path winning.
function Get-Live {
    $live = @{}
    foreach ($r in (Get-Rows $false)) {
        if (-not $r.Monitor) { continue }
        $key = $r.Monitor.ToLowerInvariant()
        if (-not $live.ContainsKey($key)) {
            $name = if ($r.Friendly) { $r.Friendly } else { 'Unnamed monitor' }
            $live[$key] = [pscustomobject]@{ name = $name; active = $false; available = $false; x = 0; y = 0; w = 0; h = 0; refresh = 0.0; rotation = 0; dpi = 0; gdi = '' }
        }
        $m = $live[$key]
        if ($r.Available) { $m.available = $true }
        if ($r.Active) {
            $m.active = $true; $m.gdi = $r.Gdi
            if ($r.RefreshDen -gt 0) { $m.refresh = [math]::Round($r.RefreshNum / $r.RefreshDen, 3) }
            $m.rotation = switch ([int]$r.Rotation) { 2 { 90 } 3 { 180 } 4 { 270 } default { 0 } }
            if ($r.HasMode) { $m.x = $r.X; $m.y = $r.Y; $m.w = $r.W; $m.h = $r.H }
            if ($r.Gdi) { $m.dpi = [int][LayoutswapSwitch.Dpi]::ForGdi($r.Gdi) }
        }
    }
    return $live
}

# Verify: compare what is on now to the summary. The on set and each on monitor's
# position and size must match; refresh, rotation and scale differences are warnings.
function Compare-Live($summary, $live) {
    $failures = @()
    $warnings = @()
    $known = @{}
    foreach ($m in $summary.monitors) {
        $key = $m.devicePath.ToLowerInvariant()
        $known[$key] = $true
        $isActive = $live.ContainsKey($key) -and $live[$key].active
        if ($m.on -and -not $isActive) { $failures += ("{0} is not on" -f $m.label); continue }
        if (-not $m.on -and $isActive) { $failures += ("{0} is on but should be off" -f $m.label); continue }
        if (-not $m.on) { continue }
        $l = $live[$key]
        if ($l.x -ne $m.x -or $l.y -ne $m.y) { $failures += ("{0} landed at {1},{2} instead of {3},{4}" -f $m.label, $l.x, $l.y, $m.x, $m.y) }
        if ($l.w -ne $m.width -or $l.h -ne $m.height) { $failures += ("{0} is {1}x{2} instead of {3}x{4}" -f $m.label, $l.w, $l.h, $m.width, $m.height) }
        if ($m.refreshHz -and [math]::Abs($l.refresh - $m.refreshHz) -gt 0.01) { $warnings += ("{0} runs at {1} Hz instead of {2} Hz" -f $m.label, $l.refresh, $m.refreshHz) }
        if ($null -ne $m.rotation -and $l.rotation -ne $m.rotation) { $warnings += ("{0} is rotated {1} instead of {2}" -f $m.label, $l.rotation, $m.rotation) }
        if ($m.scalePercent -and $l.dpi -gt 0) {
            $scale = [int][math]::Floor(($l.dpi * 100 + 48) / 96)   # same rounding as the app's probe
            if ($scale -ne $m.scalePercent) { $warnings += ("{0} is scaled {1}% instead of {2}%" -f $m.label, $scale, $m.scalePercent) }
        }
    }
    foreach ($key in $live.Keys) {
        if ($live[$key].active -and -not $known.ContainsKey($key)) { $failures += ("an extra monitor is on: {0}" -f $live[$key].name) }
    }
    return [pscustomobject]@{ failures = $failures; warnings = $warnings }
}

function Get-ApplyReason([int]$rc) {
    switch ($rc) {
        87   { 'invalid parameter, a monitor in the layout is probably not connected' }
        1610 { 'bad configuration' }
        31   { 'general failure' }
        default { "SetDisplayConfig returned $rc" }
    }
}

$ArrangeAgain = 'arrange the monitors in Windows Settings > Display, then save the layout again'

#=============================================================================
Write-Host ""
Write-Host ("=== Switch to {0} ===" -f $LayoutName) -ForegroundColor Cyan

# Only one switch at a time, from the app or from a shortcut. A lock that a crashed run
# left behind is cleared by hand; the message says where it is.
if (Test-Path $LockPath) {
    $lines = @(Get-Content $LockPath)
    $otherPid = if ($lines.Count -gt 0) { $lines[0] -replace '^pid=', '' } else { '?' }
    $other = if ($lines.Count -gt 1) { $lines[1] -replace '^layout=', '' } else { 'another layout' }
    Write-Host ("Wait for the switch to {0} to finish, then try again. If process {1} is no longer running, delete {2} first." -f $other, $otherPid, $LockPath) -ForegroundColor Yellow
    Finish 2
}
try {
    if (-not (Test-Path $AppRoot)) { New-Item -ItemType Directory -Path $AppRoot | Out-Null }
    Set-Content -Path $LockPath -Value @("pid=$PID", "layout=$LayoutName") -Encoding ASCII
} catch {
    Write-Host ("Check that {0} is writable, then try again; could not take the lock ({1})." -f $AppRoot, $_.Exception.Message) -ForegroundColor Yellow
    Finish 1
}

[LayoutswapSwitch.Dpi]::MakeAware()
$summary = ($SummaryJson | ConvertFrom-Json)
$arrangement = ($ArrangementJson | ConvertFrom-Json)

#-----------------------------------------------------------------------------
# [1/3] Check monitors: every on monitor must be Available, else stop and name the Absent ones.
#-----------------------------------------------------------------------------
Write-Step 1 'running' 'Check monitors'
try {
    $live = Get-Live
    $absent = @()
    foreach ($m in $summary.monitors) {
        if (-not $m.on) { continue }
        $key = $m.devicePath.ToLowerInvariant()
        if ($live.ContainsKey($key) -and $live[$key].available) { Write-Host ("  {0}: Available" -f $m.label) }
        else { $absent += $m.label; Write-Host ("  {0}: Absent" -f $m.label) }
    }
    if ($absent.Count -gt 0) {
        Write-Failure ("press the input button on {0}, or plug it in, then switch again" -f ($absent -join ', ')) ("{0} Absent" -f (@($absent).Count)) 0
        Finish 2
    }
    Write-Step 1 'done' 'Check monitors'
} catch {
    Write-Failure 'try the switch again' ("could not read the monitors ({0})" -f $_.Exception.Message) 0
    Finish 1
}

#-----------------------------------------------------------------------------
# [2/3] Apply arrangement: remap GPU identifiers by device path, validate, then apply.
# Already applied is a no-op with a log line, so re-running a script is safe.
#-----------------------------------------------------------------------------
Write-Step 2 'running' 'Apply arrangement'
try {
    $paths = [LayoutswapSwitch.Api]::BytesToPaths([Convert]::FromBase64String($arrangement.paths))
    $modes = [LayoutswapSwitch.Api]::BytesToModes([Convert]::FromBase64String($arrangement.modes))
    $missing = ''
    $rc = [LayoutswapSwitch.Api]::Apply($paths, $modes, [string[]]$arrangement.sourceAdapters, [string[]]$arrangement.targetAdapters, [string[]]$arrangement.modeAdapters, [ref]$missing, $true)
    if ($rc -eq -1) { Write-Failure 'save the layout again on this machine' ("the GPU it was captured on is not present: {0}" -f $missing) 0; Finish 1 }
    if ($rc -ne 0)  { Write-Failure $ArrangeAgain ("Windows rejected the arrangement before applying it, {0}" -f (Get-ApplyReason $rc)) $rc; Finish 1 }
    Write-Host "  validated"
    $already = Compare-Live $summary $live
    if ($ValidateOnly) {
        Write-Step 2 'skipped' 'Apply arrangement: validated only, nothing applied'
    } elseif ($already.failures.Count -eq 0) {
        Write-Step 2 'skipped' 'Apply arrangement: already applied'
    } else {
        $rc = [LayoutswapSwitch.Api]::Apply($paths, $modes, [string[]]$arrangement.sourceAdapters, [string[]]$arrangement.targetAdapters, [string[]]$arrangement.modeAdapters, [ref]$missing, $false)
        if ($rc -ne 0)  { Write-Failure ('try the switch again, and if it keeps failing ' + $ArrangeAgain) ("Windows could not apply the arrangement, {0}" -f (Get-ApplyReason $rc)) $rc; Finish 1 }
        Write-Host "  applied"
        Start-Sleep -Seconds $SettleSeconds
        Write-Step 2 'done' 'Apply arrangement'
    }
} catch {
    Write-Failure 'try the switch again' ("could not apply the arrangement ({0})" -f $_.Exception.Message) 0
    Finish 1
}

#-----------------------------------------------------------------------------
# [3/3] Verify: read the arrangement back and compare it to the summary.
#-----------------------------------------------------------------------------
Write-Step 3 'running' 'Verify'
try {
    $result = Compare-Live $summary (Get-Live)
    foreach ($w in $result.warnings) { Write-Host ("  warning: {0}" -f $w) -ForegroundColor Yellow }
    if ($result.failures.Count -gt 0) {
        Write-Failure $ArrangeAgain ($result.failures -join '; ') 0
        Finish 1
    }
    Write-Step 3 'done' 'Verify'
} catch {
    Write-Failure 'try the switch again' ("could not verify the arrangement ({0})" -f $_.Exception.Message) 0
    Finish 1
}

Write-Host ("Switched to {0}." -f $LayoutName) -ForegroundColor Green
Finish 0
